const mirrors = [
  "https://cdn.jsdelivr.net/gh/mattpocock/skills@main/docs/productivity/grill-me.md",
  "https://raw.githack.com/mattpocock/skills/main/docs/productivity/grill-me.md",
  "https://cdn.statically.io/gh/mattpocock/skills/main/docs/productivity/grill-me.md",
  "https://ghproxy.net/https://raw.githubusercontent.com/mattpocock/skills/main/docs/productivity/grill-me.md",
  "https://gcore.jsdelivr.net/gh/mattpocock/skills@main/docs/productivity/grill-me.md",
  "https://raw.gitmirror.com/mattpocock/skills/main/docs/productivity/grill-me.md",
];
const ps = `$u = @(${mirrors.map(m => `"${m}"`).join(",")})
$u | ForEach-Object -Parallel {
  try {
    $r = curl.exe -sS -m 12 -L $_
    if ($r) { "OK >>> $_"; $r.Substring(0, [Math]::Min(1200, $r.Length)) } else { "EMPTY >>> $_" }
  } catch { "FAIL >>> $_ :: $($_.Exception.Message)" }
} -ThrottleLimit 6`;

const [net, gr] = await Promise.all([
  tools.pwsh({ command: ps, description: "Try mirrors for grill-me source" , timeoutMs: 90000}),
  tools.grep({ pattern: "grill-?me", path: "C:\\Users\\jjq21\\.claude" }).catch(() => ({ matches: [] as any[] })),
]);
if (net.kind === "foreground") console.log(net.stdout.text.slice(0, 5000) + "\n---STDERR---\n" + net.stderr.text.slice(0, 1000));
console.log("\n=== local grep matches ===");
for (const m of (gr as any).matches.slice(0, 25)) console.log(`${m.path}:${m.lineNumber}: ${m.line.slice(0, 160)}`);
